INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 2, 'theory', 'Квиз: пакеты и обновления');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 0, 'Какая версия новее по правилам Debian: 1.0~rc1 или 1.0?', '["1.0~rc1, потому что строка длиннее", "Они равны", "1.0, потому что тильда сортируется раньше даже конца строки", "Сравнить нельзя без эпохи"]', 2, 'Тильда означает пре-релиз: часть с тильдой меньше пустой части. Отсутствующая эпоха равна нулю, так что сравнение возможно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 1, 'Что делает поле Signed-By в описании репозитория Debian?', '["Привязывает репозиторий к конкретному ключу, и другие ключи для него не годятся", "Включает проверку подписей для всех репозиториев сразу", "Указывает автора пакетов", "Отключает проверку подписи для этого источника"]', 0, 'Так ключ не становится общим доверием всей системы, как в старом apt-key: он действует только для своего источника.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 2, 'Что верно про ядра в dnf по умолчанию?', '["Хранится одно ядро, остальные удаляются сразу", "Хранится два ядра, работающее может быть удалено", "Число ядер не ограничено", "Хранится до трёх ядер, работающее ядро защищено от удаления"]', 3, 'Параметр installonly_limit по умолчанию равен трём, а protect_running_kernel включён. Значение 1 не разрешено именно из-за защиты работающего ядра.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 3, 'Что делает dnf history rollback N?', '["Отменяет только транзакцию с номером N", "Отменяет все транзакции после N, а если хоть одну нельзя отменить, не отменяет ни одной", "Переустанавливает все пакеты на состояние дистрибутива", "Восстанавливает конфигурационные файлы из резервной копии"]', 1, 'Rollback возвращает систему к состоянию после N; для одной транзакции есть undo. Если база изменилась так, что отмена невозможна, откат не выполняется вовсе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 4, 'Сторонний репозиторий отвечает ошибкой NO_PUBKEY. Что правильно?', '["Установить пакеты с флагом, разрешающим неподписанное", "Отключить проверку подписи в конфигурации", "Получить ключ от владельца по проверенному каналу и указать его в Signed-By", "Подождать час: ошибка пройдёт сама"]', 2, 'Подпись — единственное, что связывает пакет с его автором. Отключение проверки делает возможной подмену пакета, которая исполнится с правами root.');
